package eu.europa.esig.dss.cbades.extension;

import eu.europa.esig.dss.cbades.signature.CBAdESService;
import eu.europa.esig.dss.cbades.signature.CBAdESSignatureParameters;
import eu.europa.esig.dss.enumerations.SignatureForm;
import eu.europa.esig.dss.enumerations.SignatureLevel;
import eu.europa.esig.dss.enumerations.SignaturePackaging;
import eu.europa.esig.dss.model.AbstractSerializableSignatureParameters;
import eu.europa.esig.dss.model.DSSDocument;
import eu.europa.esig.dss.model.FileDocument;
import eu.europa.esig.dss.model.InMemoryDocument;
import eu.europa.esig.dss.model.SignatureValue;
import eu.europa.esig.dss.model.ToBeSigned;
import eu.europa.esig.dss.signature.DocumentSignatureService;
import eu.europa.esig.dss.spi.extension.DocumentExtender;
import eu.europa.esig.dss.test.extension.AbstractTestDocumentExtender;
import eu.europa.esig.dss.utils.Utils;

import java.util.ArrayList;
import java.util.List;

class CBAdESDocumentExtenderTest extends AbstractTestDocumentExtender {

    @Override
    protected DocumentExtender initEmptyExtender() {
        return new CBAdESDocumentExtender();
    }

    @Override
    protected DocumentExtender initExtender(DSSDocument document) {
        return new CBAdESDocumentExtender(document);
    }

    @Override
    protected List<DSSDocument> getValidDocuments() {
        List<DSSDocument> documents = new ArrayList<>();
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-level-b-rsa.cose"));
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-level-b-untagged.cose"));
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-double-b-level.cose"));
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-double-level-b-untagged.cose"));
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-cosesign1-level-t-clear-uheaders.cose"));
        documents.add(new FileDocument("src/test/resources/validation/cb-ades-cosesign-countersignatureV2-rfc9338-array.cose"));
        return documents;
    }

    @Override
    protected DSSDocument getMalformedDocument() {
        return new InMemoryDocument(Utils.fromHex(""));
    }

    @Override
    protected DSSDocument getOtherTypeDocument() {
        return new FileDocument("src/test/resources/CZ.cer");
    }

    @Override
    protected DSSDocument getSignatureDocument() {
        CBAdESService service = new CBAdESService(getCompleteCertificateVerifier());
        CBAdESSignatureParameters signatureParameters = new CBAdESSignatureParameters();
        signatureParameters.setSigningCertificate(getSigningCert());
        signatureParameters.setCertificateChain(getCertificateChain());
        signatureParameters.setSignaturePackaging(SignaturePackaging.ENVELOPING);
        signatureParameters.setSignatureLevel(SignatureLevel.CB_AdES_BASELINE_B);

        DSSDocument toSignDocument = getNoSignatureDocument();
        ToBeSigned dataToSign = service.getDataToSign(toSignDocument, signatureParameters);
        SignatureValue signatureValue = getToken().sign(dataToSign, signatureParameters.getDigestAlgorithm(), getPrivateKeyEntry());
        return service.signDocument(toSignDocument, signatureParameters, signatureValue);
    }

    @Override
    protected DSSDocument getNoSignatureDocument() {
        return new InMemoryDocument(Utils.fromHex("D8628441A0A04C48656C6C6F20576F726C642180"));
    }

    @Override
    protected DSSDocument getXmlEvidenceRecordDocument() {
        return null;
    }

    @Override
    protected SignatureForm getSignatureForm() {
        return SignatureForm.CBAdES;
    }

    @Override
    protected AbstractSerializableSignatureParameters<?> initExtensionParameters() {
        return new CBAdESSignatureParameters();
    }

    @Override
    protected DocumentSignatureService<?, ?> initService() {
        return new CBAdESService(getCompleteCertificateVerifier());
    }

    @Override
    protected String parseErrorMessage() {
        return "Document is not of a COSE signature type!";
    }

    @Override
    protected String noSignatureErrorMessage() {
        return "COSE_Sign.signatures array is empty!";
    }

}
